pub fn language(value: &str, t: &T) -> El {
    let entry = match value {
        "ts" | "typescript" => Some((&TYPESCRIPT, if t.dark { "#69b1ff" } else { "#1a85d4" })),
        "js" | "javascript" => Some((&JAVASCRIPT, if t.dark { "#ffd452" } else { "#d5a910" })),
        "json" => Some((&JSON, if t.dark { "#ffa359" } else { "#d47628" })),
        "sh" | "bash" | "shell" | "zsh" => {
            Some((&BASH, if t.dark { "#5ecc71" } else { "#199f43" }))
        }
        "py" | "python" => Some((&PYTHON, if t.dark { "#69b1ff" } else { "#1a85d4" })),
        "rs" | "rust" => Some((&RUST, if t.dark { "#ffa359" } else { "#d47628" })),
        "tsx" | "jsx" => Some((&REACT, if t.dark { "#68cdf2" } else { "#1ca1c7" })),
        "css" => Some((&CSS, if t.dark { "#9d6afb" } else { "#693acf" })),
        "html" => Some((&HTML, if t.dark { "#ffa359" } else { "#d47628" })),
        "md" | "markdown" => Some((&MARKDOWN, if t.dark { "#5ecc71" } else { "#199f43" })),
        _ => None,
    };
    match entry {
        Some((glyph, color)) => icon(glyph, 14.0)
            .color(rune::color::hex(color).unwrap_or(Color::WHITE))
            .label(value),
        None => text(value).font(theme::MONO_XS).color(t.c.muted_foreground),
    }
}
